/* Real-card data, taken from a bilinear filter diagnostic on a PCI Rage Pro
 * (1002:4750, BIOS 113-41902-106, ATI3DCIF 4.11.2692 mip-disable bug patched),
 * 640x480 at 32 bpp, dither off, no perspective correction, white vertex colour.
 * Do not edit.
 *
 * Each group is a 64x64 texture of two colours per channel (lo and hi, native
 * channel values) drawn as quads whose corners are whole pixels, with the
 * texture coordinates in texels. Quad kind 0: columns alternate lo, hi; kind 1:
 * rows alternate; kind 2: period 2 where red is hi only at (1, 0), green only at
 * (0, 1), blue only at (1, 1) and all lo at (0, 0). Texture format 0 RGB565, 1
 * ARGB1555, 2 ARGB4444, 3 VQ (a codebook of RGB565 words, every 2x2 block entry
 * 0). A probe is a pixel and the 24 bit colour the card wrote there. The d groups
 * are minified 2:1 and 4:1 with the minifying filter set, one pixel per texel
 * step; the others are magnified 128 pixels per texel (also 64 vertically for
 * the second quad of kind 2). */
struct bilinear_probe {
    unsigned short x, y;
    unsigned       rgb;
};
struct bilinear_quad {
    int    x0, y0, x1, y1;
    double u0, v0, u1, v1;
    int    kind;
    int    count;
    int    first;
};
struct bilinear_group {
    const char                 *name;
    int                         format, lo[3], hi[3], nquad;
    const struct bilinear_quad *quads;
};
